question.solution:
def first_fit_alloc(free_list, size):
    for i in range(len(free_list)):
        if free_list[i][1] >= size:
            start = free_list[i][0]
            free_list[i][0] += size
            free_list[i][1] -= size
            if free_list[i][1] == 0:
                del free_list[i]
            return start
    return -1

